--[[ ============================================================
     NX Bundle Animations · VERSION PORTATIL (self-contained)
     Pega y ejecuta. Escribe los datos en tu executor la 1a vez
     y luego abre el panel (RightShift). No copies carpetas.
     ============================================================ ]]
do
    local DIR   = "BundleAnimations"
    local CACHE = DIR .. "/anims_cache.json"
    local CONF  = DIR .. "/config.json"
    local hasWrite = (typeof(writefile) == "function")
    local hasMake  = (typeof(makefolder) == "function")
    local hasFile  = (typeof(isfile) == "function")
    local hasFold  = (typeof(isfolder) == "function")
    if hasWrite then
        pcall(function()
            if hasMake and not (hasFold and isfolder(DIR)) then makefolder(DIR) end
        end)
        -- solo reescribe el cache (200KB) si falta o cambió · antes lo escribía en CADA ejecución
        pcall(function()
            local same = false
            if hasFile and isfile(CACHE) then
                local ok, cur = pcall(readfile, CACHE)
                same = ok and cur and #cur == #_NX_EMBED_CACHE
            end
            if not same then writefile(CACHE, _NX_EMBED_CACHE) end
        end)
        pcall(function()
            if not (hasFile and isfile(CONF)) then writefile(CONF, _NX_EMBED_CONFIG) end
        end)
    else
        warn("[NX Portable] Tu executor no soporta writefile.")
    end
end

