-- ========================== RESOLVE CACHE (★ DECLARADO ANTES DE saveConfig) ==========================
-- ★ FIX LAG (raíz): antes `resolveCache` se declaraba DESPUÉS de saveConfig, así que dentro
-- de saveConfig la variable NO era la local — era un global nil. Cada saveConfig() ponía
-- cfg.resolveCache = nil → borraba la llave del JSON. El mapa wrapper→real se perdía SIEMPRE
-- y cada apply volvía a descargar todos los assets con GetObjects. Ese era el lag.
local resolveCache = {}
local resolveFail  = {}   -- solo memoria: ids que fallaron esta sesión (no re-descargar en bucle)
if type(rawConfig.resolveCache) == "table" then
    for k, v in pairs(rawConfig.resolveCache) do
        resolveCache[tostring(k)] = tostring(v)
    end
end

-- persistencia DIFERIDA: antes escribía el JSON completo por CADA id resuelto
-- (hasta ~10 writefile por apply). Ahora marca sucio y guarda una sola vez.
local resolveDirty, resolveQueued = false, false
local function persistResolveCache()
    resolveDirty = true
    if resolveQueued then return end
    resolveQueued = true
    task.delay(0.5, function()
        resolveQueued = false
        if not resolveDirty then return end
        resolveDirty = false
        pcall(function()
            local cfg = safeDecode(safeRead(CONFIG_PATH)) or {}
            cfg.resolveCache = resolveCache
            writefile(CONFIG_PATH, HttpService:JSONEncode(cfg))
        end)
    end)
end

-- ========================== PERSISTENCIA (merge, no clobbea) ==========================
local function saveConfig()
    pcall(function()
        local cfg = safeDecode(safeRead(CONFIG_PATH)) or {}
        -- favoritos (con fecha)
        local favTbl = {}
        for bid, meta in pairs(favorites) do
            local ts = (type(meta) == "table" and meta.addedAt) or os.time()
            favTbl[bid] = { name = NAMES[bid] or ("Bundle " .. bid), kind = "bundle", addedAt = ts }
        end
        cfg.favorites = favTbl
        -- mix (preset)
        local mixTbl = {}
        for atype, bid in pairs(mixSlots) do
            if bid then mixTbl[atype] = { id = bid, name = NAMES[bid] or ("Bundle " .. bid) } end
        end
        cfg.mix      = mixTbl
        cfg.full     = activeFull   -- nil => la llave se omite del JSON
        cfg.lastMode = activeMode
        cfg.autoLoad = autoLoad
        cfg.resolveCache = resolveCache   -- persistir mapa wrapper→real (no clobber)
        writefile(CONFIG_PATH, HttpService:JSONEncode(cfg))
    end)
end

-- ========================== MOTOR DE ANIMACIÓN (INTACTO) ==========================
local ANIMATE_FOLDERS = {"idle","walk","run","jump","fall","climb","swim","swimidle","sit"}
local FOLDERS_FOR = {
    IdleAnimation = {"idle"}, WalkAnimation = {"walk"}, RunAnimation = {"run"},
    JumpAnimation = {"jump"}, FallAnimation = {"fall"}, ClimbAnimation = {"climb"},
    SwimAnimation = {"swim", "swimidle"},
}

local function getAnimateScript()
    local char = LP.Character
    if not char then return nil end
    return char:FindFirstChild("Animate")
end

local function folderForTrack(animType, trackName)
    if animType == "SwimAnimation" then
        if string.find(string.lower(trackName), "idle") then return "swimidle" end
        return "swim"
    end
    return string.lower((string.gsub(animType, "Animation", "")))
end

local function backupOriginals()
    if next(originalAnims) ~= nil then return end
    local animate = getAnimateScript()
    if not animate then return end
    for _, fname in ipairs(ANIMATE_FOLDERS) do
        local folder = animate:FindFirstChild(fname)
        if folder then
            originalAnims[fname] = {}
            for _, child in ipairs(folder:GetChildren()) do
                if child:IsA("Animation") then
                    table.insert(originalAnims[fname], {name = child.Name, id = child.AnimationId})
                end
            end
        end
    end
end

local function reloadAnimate()
    local animate = getAnimateScript()
    if not animate then return end
    local char = LP.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    local animator = hum and hum:FindFirstChildOfClass("Animator")
    if animator then
        pcall(function()
            for _, t in ipairs(animator:GetPlayingAnimationTracks()) do t:Stop(0) end
        end)
    end
    pcall(function()
        animate.Disabled = true
        task.wait(0.05)
        animate.Disabled = false
    end)
end

-- ================= RESOLVER: catalog wrapper → AnimationId REAL =================
-- Los bundles UGC nuevos guardan el "catalog item ID" (envoltorio) en items[].id.
-- Ese ID NO reproduce en Animation.AnimationId — hay que abrir el asset y leer el
-- AnimationId REAL desde adentro. Solo el executor tiene auth para hacerlo, por eso
-- lo resolvemos en runtime y lo cacheamos en config.json.
-- (resolveCache / persistResolveCache viven arriba, antes de saveConfig · ver ★ FIX LAG)

local function extractAnimId(inst)
    if not inst then return nil end
    if typeof(inst) == "Instance" and inst:IsA("Animation") then
        local m = tostring(inst.AnimationId):match("(%d+)")
        if m then return m end
    end
    if typeof(inst) == "Instance" then
        for _, c in ipairs(inst:GetDescendants()) do
            if c:IsA("Animation") then
                local m = tostring(c.AnimationId):match("(%d+)")
                if m then return m end
            end
        end
    end
    return nil
end

-- ¿este id necesita una descarga? (para no llamar a GetObjects de gratis)
local function needsFetch(url)
    local id = tostring(url):match("(%d+)")
    if not id or #id < 12 then return false end          -- clásico Roblox = ya es real
    if resolveCache[id] or resolveFail[id] then return false end
    return true
end

local resolveInflight = {}   -- id → true mientras se descarga (evita bajar 2 veces lo mismo)

local function fetchRealId(id)
    -- resolver via executor (game:GetObjects funciona con auth)
    local ok, objs = pcall(function() return game:GetObjects("rbxassetid://" .. id) end)
    if ok and objs and objs[1] then
        local real = extractAnimId(objs[1])
        if real then return real end
    end
    -- fallback: InsertService (algunos executors lo permiten)
    local ok2, asset = pcall(function()
        return game:GetService("InsertService"):LoadAsset(tonumber(id))
    end)
    if ok2 and asset then
        local real = extractAnimId(asset)
        pcall(function() asset:Destroy() end)
        if real then return real end
    end
    return nil
end

local function resolveAnimId(url)
    local id = tostring(url):match("(%d+)")
    if not id then return url end
    -- IDs cortos = clásicos Roblox = ya son reales
    if #id < 12 then return url end
    -- cache hit
    if resolveCache[id] then return "rbxassetid://" .. resolveCache[id] end
    -- ya falló esta sesión → no re-descargar en cada apply
    if resolveFail[id] then return url end
    -- alguien más ya lo está bajando → esperar su resultado en vez de duplicar la descarga
    if resolveInflight[id] then
        local t0 = os.clock()
        while resolveInflight[id] and os.clock() - t0 < 10 do task.wait() end
        if resolveCache[id] then return "rbxassetid://" .. resolveCache[id] end
        return url
    end

    resolveInflight[id] = true
    local real = fetchRealId(id)
    resolveInflight[id] = nil

    if real then
        resolveCache[id] = real          -- si real == id, igual se cachea: "ya es real"
        persistResolveCache()
        return "rbxassetid://" .. real
    end
    resolveFail[id] = true   -- no se pudo; no reintentar hasta la próxima sesión
    return url
end

-- ★ resuelve una tanda EN PARALELO. Antes se resolvía track por track en serie:
-- 7 tipos × 1-3 tracks ≈ 10 descargas encadenadas = el freeze al aplicar un pack nuevo.
local function resolveParallel(urls)
    local out, pending = {}, 0
    for i, u in ipairs(urls) do
        if not needsFetch(u) then
            out[i] = resolveAnimId(u)          -- instantáneo (cache o id corto)
        else
            pending = pending + 1
            task.spawn(function()
                local ok, res = pcall(resolveAnimId, u)
                out[i] = (ok and res) or u
                pending = pending - 1
            end)
        end
    end
    if pending > 0 then
        local t0 = os.clock()
        while pending > 0 and os.clock() - t0 < 10 do task.wait() end
    end
    for i, u in ipairs(urls) do out[i] = out[i] or u end
    return out
end

local ContentProvider = game:GetService("ContentProvider")
local function preloadBg(list)
    if #list == 0 then return end
    task.spawn(function() pcall(function() ContentProvider:PreloadAsync(list) end) end)
end

-- ================= ★ NX FETCH EN VIVO: cualquier bundle del catálogo =================
-- Baja bajo demanda CUALQUIER pack de animación de Roblox (no solo los 310 precargados),
-- lo arma en la estructura del DB y lo guarda en anims_cache.json (una vez → permanente).
-- Usa la sesión del executor: NO necesita tu cuenta ni login, solo estar dentro del juego.

-- HTTP portátil: prueba las funciones que exponen los executors más comunes
local function nxHttpGet(url)
    local tries = {
        function() return syn and syn.request and syn.request({Url=url, Method="GET"}).Body end,
        function() return http and http.request and http.request({Url=url, Method="GET"}).Body end,
        function() return http_request and http_request({Url=url, Method="GET"}).Body end,
        function() return request and request({Url=url, Method="GET"}).Body end,
        function() return fluxus and fluxus.request and fluxus.request({Url=url, Method="GET"}).Body end,
        function() return game.HttpGet and game:HttpGet(url) end,
        function() return game.HttpGetAsync and game:HttpGetAsync(url) end,
    }
    for _, fn in ipairs(tries) do
        local ok, res = pcall(fn)
        if ok and type(res) == "string" and #res > 0 then return res end
    end
    return nil
end

-- nombre (de carpeta / item / animación) → tipo de animación del DB
local function nxAnimType(name)
    name = string.lower(tostring(name or ""))
    if name:find("swim") then return "SwimAnimation", (name:find("idle") ~= nil) end
    if name:find("walk")  then return "WalkAnimation"  end
    if name:find("run")   then return "RunAnimation"   end
    if name:find("idle")  then return "IdleAnimation"  end
    if name:find("jump")  then return "JumpAnimation"  end
    if name:find("fall")  then return "FallAnimation"  end
    if name:find("climb") then return "ClimbAnimation" end
    return nil
end

-- recorre un objeto ya cargado (game:GetObjects) y clasifica cada Animation que encuentre
local function nxCollect(entry, root, hintName)
    if typeof(root) ~= "Instance" then return end
    local anims = {}
    if root:IsA("Animation") then anims[1] = root
    else for _, d in ipairs(root:GetDescendants()) do if d:IsA("Animation") then anims[#anims+1] = d end end end
    for _, a in ipairs(anims) do
        local id = tostring(a.AnimationId):match("(%d+)")
        if id and id ~= "0" then
            -- clasifica subiendo por los padres (carpetas idle/walk/run...), luego hint, luego nombre
            local atype, isSwimIdle, matched
            local node = a.Parent
            for _ = 1, 6 do
                if not node or node == workspace then break end
                local t, s = nxAnimType(node.Name)
                if t then atype, isSwimIdle, matched = t, s, node.Name; break end
                node = node.Parent
            end
            if not atype then atype, isSwimIdle, matched = nxAnimType(a.Name) ; matched = a.Name end
            if not atype then atype, isSwimIdle, matched = nxAnimType(hintName) ; matched = hintName end
            if atype then
                entry[atype] = entry[atype] or {}
                local track
                if atype == "IdleAnimation" then
                    local n = 0; for _ in pairs(entry[atype]) do n = n + 1 end
                    track = "Animation" .. (n + 1)
                elseif atype == "SwimAnimation" then
                    track = isSwimIdle and "SwimIdleAnim" or "SwimAnim"
                else
                    track = ({WalkAnimation="WalkAnim", RunAnimation="RunAnim", JumpAnimation="JumpAnim",
                              FallAnimation="FallAnim", ClimbAnimation="ClimbAnim"})[atype]
                end
                if track and not entry[atype][track] then
                    entry[atype][track] = "rbxassetid://" .. id
                end
            end
        end
    end
end

-- guarda el DB completo al archivo (persistente entre sesiones)
local function nxSaveDB()
    pcall(function()
        if typeof(writefile) == "function" then
            writefile(CACHE_PATH, HttpService:JSONEncode(DB))
        end
    end)
end

-- baja un bundle por ID, arma su entrada en DB y la persiste. Devuelve la entrada o nil.
local function fetchBundleLive(bundleId)
    bundleId = tostring(bundleId)
    if DB[bundleId] then return DB[bundleId] end
    local entry, realName = {}, nil

    -- A) detalles del bundle vía web (items = cada animación como asset del catálogo)
    local body = nxHttpGet("https://catalog.roblox.com/v1/bundles/" .. bundleId .. "/details")
    local data = body and safeDecode(body)
    if type(data) == "table" then
        realName = data.name or data.Name
        local items = data.items or data.Items
        if type(items) == "table" then
            -- ★ FIX LAG: baja TODOS los items del bundle EN PARALELO. Antes era una serie
            -- bloqueante (un game:GetObjects tras otro) → freeze grande al pegar un link.
            local results, pending = {}, 0
            for i, it in ipairs(items) do
                local itId   = it.id or it.Id
                local itType = tostring(it.type or it.Type or "")
                if itId and (itType == "Asset" or itType == "UserOutfit" or itType == "") then
                    pending = pending + 1
                    task.spawn(function()
                        local ok, objs = pcall(function() return game:GetObjects("rbxassetid://" .. itId) end)
                        results[i] = { objs = (ok and objs) or nil, hint = it.name or it.Name }
                        pending = pending - 1
                    end)
                end
            end
            if pending > 0 then
                local t0 = os.clock()
                while pending > 0 and os.clock() - t0 < 15 do task.wait() end
            end
            -- collect EN ORDEN (evita choques al numerar IdleAnimation1/2/3)
            for i = 1, #items do
                local r = results[i]
                if r and r.objs then for _, o in ipairs(r.objs) do nxCollect(entry, o, r.hint) end end
            end
        end
    end

    -- B) fallback sin web: AvatarEditorService (usa tu sesión del juego)
    if next(entry) == nil then
        pcall(function()
            local AES = game:GetService("AvatarEditorService")
            local det = AES:GetItemDetails(tonumber(bundleId), Enum.AvatarItemType.Bundle)
            if det then
                realName = realName or det.Name
                local bi = det.BundledItems or det.bundledItems
                if type(bi) == "table" then
                    -- ★ FIX LAG: igual que la ruta A, en PARALELO en vez de en serie.
                    local results, pending = {}, 0
                    for i, it in ipairs(bi) do
                        local itId = it.Id or it.id
                        if itId and tostring(it.Type or it.type) == "Asset" then
                            pending = pending + 1
                            task.spawn(function()
                                local ok, objs = pcall(function() return game:GetObjects("rbxassetid://" .. itId) end)
                                results[i] = { objs = (ok and objs) or nil, hint = it.Name or it.name }
                                pending = pending - 1
                            end)
                        end
                    end
                    if pending > 0 then
                        local t0 = os.clock()
                        while pending > 0 and os.clock() - t0 < 15 do task.wait() end
                    end
                    for i = 1, #bi do
                        local r = results[i]
                        if r and r.objs then for _, o in ipairs(r.objs) do nxCollect(entry, o, r.hint) end end
                    end
                end
            end
        end)
    end

    -- C) último recurso: tratar el ID como asset directo (packs clásicos empaquetados)
    if next(entry) == nil then
        local ok, objs = pcall(function() return game:GetObjects("rbxassetid://" .. bundleId) end)
        if ok and objs then for _, o in ipairs(objs) do nxCollect(entry, o, nil) end end
    end

    if next(entry) == nil then return nil end   -- no se pudo resolver nada

    DB[bundleId] = entry
    if realName and realName ~= "" then
        NAMES[bundleId] = realName
        for _, e in ipairs(CATALOG) do if e[1] == bundleId then e[2] = realName; break end end
    end
    nxSaveDB()
    return entry
end

-- FASE 1 · puede tardar (descarga) pero NO toca el personaje
local function prepareBundle(animType, bundleId)
    local bundleData = DB[bundleId]
    if not bundleData then bundleData = fetchBundleLive(bundleId) end   -- ★ auto-descarga si no está en cache
    if not bundleData or not bundleData[animType] then return nil end
    local names, urls = {}, {}
    for trackName, url in pairs(bundleData[animType]) do
        names[#names + 1] = trackName
        urls[#urls + 1]   = url
    end
    -- ★ los 271 packs originales ya traen el AnimationId real → CERO red, instantáneo
    local ids = urls
    if WRAPPER_PACKS[bundleId] then ids = resolveParallel(urls) end
    local byFolder = {}
    for i, trackName in ipairs(names) do
        local fname = folderForTrack(animType, trackName)
        byFolder[fname] = byFolder[fname] or {}
        table.insert(byFolder[fname], {name = trackName, id = ids[i]})
    end
    return byFolder
end

-- FASE 2 · swap real: instantáneo, sin un solo yield (el personaje no queda a medias)
local function commitPrepared(byFolder)
    local animate = getAnimateScript()
    if not (animate and byFolder) then return false end
    local created = {}
    for fname, list in pairs(byFolder) do
        local folder = animate:FindFirstChild(fname)
        if folder then
            for _, child in ipairs(folder:GetChildren()) do
                if child:IsA("Animation") then child:Destroy() end
            end
            for _, t in ipairs(list) do
                local a = Instance.new("Animation")
                a.Name = t.name; a.AnimationId = t.id; a.Parent = folder
                created[#created + 1] = a
            end
        end
    end
    preloadBg(created)   -- precarga en 2do plano → no tironea al primer paso/salto
    return true
end

local function applyBundle(animType, bundleId)   -- compat: prepare + commit
    local prep = prepareBundle(animType, bundleId)
    if not prep then return false end
    return commitPrepared(prep)
end

-- ¿todo el pack ya está cacheado? (para saber si hay que avisar "cargando")
local function bundleCached(bid)
    local d = DB[bid]
    if not d then return true end
    if not WRAPPER_PACKS[bid] then return true end   -- no necesita red
    for _, tracks in pairs(d) do
        if type(tracks) == "table" then
            for _, url in pairs(tracks) do
                if needsFetch(url) then return false end
            end
        end
    end
    return true
end

local function applyFullMix()  -- aplica lo que haya en currentMix (proyección)
    backupOriginals()
    local animate = getAnimateScript()
    if not animate then return end
    -- FASE 1: resolver TODOS los tipos en una sola tanda paralela
    local preps, pending = {}, 0
    for _, atype in ipairs(ANIM_TYPES) do
        local bid = currentMix[atype]
        if bid and DB[bid] then
            pending = pending + 1
            task.spawn(function()
                local ok, res = pcall(prepareBundle, atype, bid)
                preps[atype] = ok and res or nil
                pending = pending - 1
            end)
        end
    end
    if pending > 0 then
        local t0 = os.clock()
        while pending > 0 and os.clock() - t0 < 12 do task.wait() end
    end
    -- FASE 2: commit de golpe + un solo reload
    for _, atype in ipairs(ANIM_TYPES) do
        if preps[atype] then commitPrepared(preps[atype]) end
    end
    reloadAnimate()
    isApplied = true
end

local function restoreOriginals()
    local animate = getAnimateScript()
    if not animate then return end
    for fname, list in pairs(originalAnims) do
        local folder = animate:FindFirstChild(fname)
        if folder then
            for _, child in ipairs(folder:GetChildren()) do
                if child:IsA("Animation") then child:Destroy() end
            end
            for _, t in ipairs(list) do
                local a = Instance.new("Animation")
                a.Name = t.name; a.AnimationId = t.id; a.Parent = folder
            end
        end
    end
    reloadAnimate()
    isApplied = false
end

local function revertSlot(atype)
    local animate = getAnimateScript()
    if not animate then return end
    for _, fname in ipairs(FOLDERS_FOR[atype] or {}) do
        local folder = animate:FindFirstChild(fname)
        local orig = originalAnims[fname]
        if folder and orig then
            for _, ch in ipairs(folder:GetChildren()) do
                if ch:IsA("Animation") then ch:Destroy() end
            end
            for _, t in ipairs(orig) do
                local a = Instance.new("Animation"); a.Name = t.name; a.AnimationId = t.id; a.Parent = folder
            end
        end
    end
    reloadAnimate()
end

-- ========================== PROYECCIÓN FULL / MIX ==========================
local function projectFull(bid)
    table.clear(currentMix)
    for _, atype in ipairs(ANIM_TYPES) do
        if DB[bid] and DB[bid][atype] then currentMix[atype] = bid end
    end
end
local function projectMix()
    table.clear(currentMix)
    for atype, bid in pairs(mixSlots) do
        if bid then currentMix[atype] = bid end
    end
end

-- ========================== HELPERS DE DATOS ==========================
local function animCount(bid)
    local n = 0
    for _ in pairs(DB[bid] or {}) do n = n + 1 end
    return n
end
local function coverageText(bid)
    local parts = {}
    for _, atype in ipairs(ANIM_TYPES) do
        if DB[bid] and DB[bid][atype] then parts[#parts + 1] = ANIM_SHORT[atype] end
    end
    if #parts == 0 then return "sin datos" end
    if #parts >= #ANIM_TYPES then return "Completo · 7 tracks" end
    return table.concat(parts, "·")
end
local function bundleActive(bid)
    if activeFull == bid then return true end
    for _, atype in ipairs(ANIM_TYPES) do
        if mixSlots[atype] == bid then return true end
    end
    return false
end

local function buildAnimsArray(query)
    local q = string.lower(query or "")
    if q ~= "" then
        local arr = {}
        for _, e in ipairs(CATALOG) do
            if string.find(string.lower(e[2]), q, 1, true) then arr[#arr + 1] = e end
        end
        return arr
    end
    -- sin búsqueda: COMUNES arriba, luego TODAS
    local out, seen = {}, {}
    out[#out + 1] = { "##DIV##", "COMUNES" }
    for _, bid in ipairs(COMUNES) do
        if DB[bid] and not seen[bid] then
            seen[bid] = true
            out[#out + 1] = { bid, NAMES[bid] or ("Bundle " .. bid) }
        end
    end
    out[#out + 1] = { "##DIV##", "TODAS LAS ANIMACIONES" }
    for _, e in ipairs(CATALOG) do
        if not seen[e[1]] then out[#out + 1] = e end
    end
    return out
end

local function buildFavArray()
    local tmp = {}
    for bid, meta in pairs(favorites) do
        tmp[#tmp + 1] = { bid = bid, ts = (type(meta) == "table" and meta.addedAt) or 0 }
    end
    table.sort(tmp, function(a, b) return a.ts > b.ts end)   -- más recientes primero
    local out = {}
    for _, e in ipairs(tmp) do out[#out + 1] = { e.bid, NAMES[e.bid] or ("Bundle " .. e.bid) } end
    return out
end

local function toggleFav(bid)
    if favorites[bid] then
        favorites[bid] = nil
    else
        favSeq = favSeq + 1
        favorites[bid] = { addedAt = os.time() * 1000 + favSeq }
    end
    saveConfig()
end

