    STAR     = Color3.fromRGB(255, 205, 75),
    RED      = Color3.fromRGB(233, 86, 106),
    DISABLED = Color3.fromRGB(70, 74, 90),
}
local FONT      = Font.fromEnum(Enum.Font.Gotham)
local FONT_SEMI = Font.fromEnum(Enum.Font.GothamMedium)
local FONT_BOLD = Font.fromEnum(Enum.Font.GothamBold)

local DUR_FAST, DUR_MED, DUR_SLOW = 0.12, 0.20, 0.34

-- helpers UI
local function corner(inst, r)
    local c = Instance.new("UICorner"); c.CornerRadius = UDim.new(0, r); c.Parent = inst; return c
end
local function stroke(inst, col, th, tr)
    local s = Instance.new("UIStroke")
    s.Color = col; s.Thickness = th or 1; s.Transparency = tr or 0
    s.ApplyStrokeMode = Enum.ApplyStrokeMode.Border; s.Parent = inst; return s
end
local function glassStroke(inst, tr, th)
    local s = stroke(inst, C.WHITE, th or 1.2, tr or 0.6)
    local g = Instance.new("UIGradient", s)
    g.Rotation = 90
    g.Color = ColorSequence.new(Color3.fromRGB(150, 200, 255), Color3.fromRGB(30, 40, 62))
    return s
end
local function specular(parent, y, h, tr)
    local s = Instance.new("Frame")
    s.Size = UDim2.new(1, -16, 0, h or 1); s.Position = UDim2.new(0, 8, 0, y or 1)
    s.BackgroundColor3 = C.WHITE; s.BackgroundTransparency = tr or 0.6
    s.BorderSizePixel = 0; s.Active = false; s.Parent = parent
    corner(s, math.floor((h or 1) / 2))
    local g = Instance.new("UIGradient", s)
    g.Transparency = NumberSequence.new({
        NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.5, 0), NumberSequenceKeypoint.new(1, 1),
    })
    return s
end
local function pad(inst, l, r, t, b)
    local p = Instance.new("UIPadding")
    p.PaddingLeft = UDim.new(0, l or 0); p.PaddingRight = UDim.new(0, r or 0)
    p.PaddingTop = UDim.new(0, t or 0); p.PaddingBottom = UDim.new(0, b or 0)
    p.Parent = inst; return p
end
local function tween(inst, t, props, style, dir)
    local tw = TweenService:Create(inst, TweenInfo.new(t, style or Enum.EasingStyle.Quint, dir or Enum.EasingDirection.Out), props)
    tw:Play(); return tw
end
local function addPress(btn)
    local sc = Instance.new("UIScale"); sc.Parent = btn
    btn.MouseButton1Down:Connect(function() tween(sc, 0.08, {Scale = 0.96}) end)
    btn.MouseButton1Up:Connect(function() tween(sc, 0.14, {Scale = 1}, Enum.EasingStyle.Back) end)
    btn.MouseLeave:Connect(function() tween(sc, 0.12, {Scale = 1}) end)
    return sc
end
local function thumbUrl(bid) return "rbxthumb://type=BundleThumbnail&id=" .. tostring(bid) .. "&w=150&h=150" end
local function makeThumb(sz, radius)
    local holder = Instance.new("Frame")
    holder.Size = UDim2.new(0, sz, 0, sz); holder.BackgroundColor3 = C.BG; holder.BorderSizePixel = 0
    corner(holder, radius or 8); stroke(holder, C.ACCENT, 1, 0.55)
    local img = Instance.new("ImageLabel")
    img.Size = UDim2.new(1, 0, 1, 0); img.BackgroundTransparency = 1
    img.ScaleType = Enum.ScaleType.Crop; img.Image = ""; img.Parent = holder
    corner(img, radius or 8)
    return holder, img
end
local function mkButton(parent, text, w, h, kind)
    local b = Instance.new("TextButton")
    b.Size = UDim2.new(0, w, 0, h); b.AutoButtonColor = false; b.FontFace = FONT_SEMI
    b.Text = text; b.TextSize = 13; b.BorderSizePixel = 0; b.Parent = parent
    corner(b, 9)
    local base, txt, strokeCol, baseT
    if kind == "primary" then base = C.ACCENT; baseT = 0.1;  txt = C.WHITE; strokeCol = C.ACCENT_2
    elseif kind == "danger" then base = C.RED; baseT = 0.72; txt = C.RED;   strokeCol = C.RED
    else base = C.ROW; baseT = 0.0; txt = C.TEXT_HI; strokeCol = C.WHITE end
    b.BackgroundColor3 = base; b.BackgroundTransparency = baseT; b.TextColor3 = txt
    stroke(b, strokeCol, 1, kind == "primary" and 0.3 or 0.6)
    b.MouseEnter:Connect(function() tween(b, DUR_FAST, {BackgroundTransparency = math.max(0, baseT - 0.18)}) end)
    b.MouseLeave:Connect(function() tween(b, DUR_FAST, {BackgroundTransparency = baseT}) end)
    addPress(b)
    return b
end

