-- ========================================================================
-- =====================  LISTA VIRTUAL (con dividers)  ===================
-- ========================================================================
local ROW_H = 64
local POOL_N = 16
-- opts (todos opcionales):
--   showStar  → muestra ☆/★ favorito           (def: true)
--   showAct   → muestra botón "Aplicar"          (def: true)
--   actLabel  → texto del botón acción           (def: "Aplicar")
--   isActive  → fn(bid)->bool para resaltar sel. (def: nil = sin resaltado)
local function makeVirtualList(parent, posY, onClick, onFav, opts)
    opts = opts or {}
    local showStar = opts.showStar ~= false
    local showAct  = opts.showAct  ~= false
    local actLabel = opts.actLabel or "Aplicar"
    local isActive = opts.isActive   -- nil => ninguna fila se resalta

    -- reserva a la derecha según los controles visibles
    local rightPad = 12
    if showAct  then rightPad = rightPad + 78 end
    if showStar then rightPad = rightPad + 32 end

    local sf = Instance.new("ScrollingFrame", parent)
    sf.BackgroundTransparency = 1; sf.BorderSizePixel = 0
    sf.Position = UDim2.new(0, 0, 0, posY); sf.Size = UDim2.new(1, 0, 1, -posY)
    sf.ScrollBarThickness = 4; sf.ScrollBarImageColor3 = C.ACCENT; sf.ScrollBarImageTransparency = 0.3
    sf.CanvasSize = UDim2.new(0, 0, 0, 0); sf.ScrollingDirection = Enum.ScrollingDirection.Y

    local emptyLbl = Instance.new("TextLabel", sf)
    emptyLbl.BackgroundTransparency = 1; emptyLbl.Size = UDim2.new(1, 0, 0, 60); emptyLbl.Position = UDim2.new(0, 0, 0, 24)
    emptyLbl.FontFace = FONT; emptyLbl.Text = ""; emptyLbl.TextSize = 13; emptyLbl.TextColor3 = C.TEXT_MID
    emptyLbl.TextWrapped = true; emptyLbl.Visible = false; emptyLbl.ZIndex = 3

    local pool, data = {}, {}

    local function createRow()
        local f = Instance.new("TextButton", sf)
        f.Size = UDim2.new(1, -10, 0, ROW_H - 6); f.BackgroundColor3 = C.ROW; f.BackgroundTransparency = 0.0
        f.AutoButtonColor = false; f.Text = ""; f.Visible = false
        corner(f, 12)
        local st = glassStroke(f, 0.62, 1.1)
        local stAccent = stroke(f, C.ACCENT, 1.4, 0.25); stAccent.Enabled = false
        specular(f, 1, 1, 0.7)
        local th, img = makeThumb(48, 9); th.Position = UDim2.new(0, 9, 0.5, -24); th.Parent = f
        local nm = Instance.new("TextLabel", f)
        nm.BackgroundTransparency = 1; nm.Position = UDim2.new(0, 66, 0, 11); nm.Size = UDim2.new(1, -(66 + rightPad), 0, 20)
        nm.FontFace = FONT_SEMI; nm.Text = ""; nm.TextSize = 14; nm.TextColor3 = C.TEXT_HI
        nm.TextXAlignment = Enum.TextXAlignment.Left; nm.TextTruncate = Enum.TextTruncate.AtEnd
        local sub = Instance.new("TextLabel", f)
        sub.BackgroundTransparency = 1; sub.Position = UDim2.new(0, 66, 0, 33); sub.Size = UDim2.new(1, -(66 + rightPad), 0, 16)
        sub.FontFace = FONT; sub.Text = ""; sub.TextSize = 11; sub.TextColor3 = C.TEXT_MID
        sub.TextXAlignment = Enum.TextXAlignment.Left; sub.TextTruncate = Enum.TextTruncate.AtEnd

        -- ☆ favorito (opcional)
        local star = Instance.new("TextButton", f)
        star.AnchorPoint = Vector2.new(1, 0.5); star.Size = UDim2.new(0, 30, 0, 30)
        star.Position = UDim2.new(1, showAct and -86 or -12, 0.5, 0)
        star.BackgroundTransparency = 1; star.FontFace = FONT_BOLD; star.Text = "☆"; star.TextSize = 18
        star.TextColor3 = C.TEXT_LO; star.AutoButtonColor = false; star.Visible = showStar

        -- acción "Aplicar" (pill) ó marcador de selección (mixer)
        local act = Instance.new("TextButton", f)
        act.AnchorPoint = Vector2.new(1, 0.5); act.Position = UDim2.new(1, -12, 0.5, 0)
        act.FontFace = FONT_SEMI; act.AutoButtonColor = false
        if showAct then
            act.Size = UDim2.new(0, 72, 0, 30); act.BackgroundColor3 = C.ACCENT; act.BackgroundTransparency = 0.82
            act.Text = actLabel; act.TextSize = 12; act.TextColor3 = C.ACCENT_2
            corner(act, 8); stroke(act, C.ACCENT, 1, 0.45)
        else
            act.Size = UDim2.new(0, 26, 0, 26); act.BackgroundTransparency = 1
            act.Text = ""; act.TextSize = 16; act.TextColor3 = C.ACCENT; act.Active = false
        end

        -- label de divider (oculto por defecto)
        local divLbl = Instance.new("TextLabel", f)
        divLbl.BackgroundTransparency = 1; divLbl.Position = UDim2.new(0, 12, 0, 0); divLbl.Size = UDim2.new(1, -24, 1, 0)
        divLbl.FontFace = FONT_BOLD; divLbl.Text = ""; divLbl.TextSize = 11; divLbl.TextColor3 = C.ACCENT_2
        divLbl.TextXAlignment = Enum.TextXAlignment.Left; divLbl.TextYAlignment = Enum.TextYAlignment.Bottom
        divLbl.Visible = false

        local r = { frame=f, img=img, thumb=th, name=nm, sub=sub, star=star, act=act,
                    st=st, stAccent=stAccent, divLbl=divLbl, bid=nil, active=false, isDiv=false }

        f.MouseEnter:Connect(function()
            if r.isDiv then return end
            tween(f, DUR_FAST, {BackgroundColor3 = C.ROW_HOV})
        end)
        f.MouseLeave:Connect(function()
            if r.isDiv then return end
            tween(f, DUR_FAST, {BackgroundColor3 = r.active and C.ROW_HOV or C.ROW})
        end)
        addPress(f)
        f.MouseButton1Click:Connect(function()
            if r.isDiv or not r.bid then return end
            onClick(r.bid)
        end)
        if showAct then
            addPress(act)
            act.MouseButton1Click:Connect(function()
                if r.isDiv or not r.bid then return end
                onClick(r.bid)
            end)
        end
        if showStar then
            star.MouseButton1Click:Connect(function()
                if r.isDiv or not r.bid then return end
                toggleFav(r.bid)
                local fav = favorites[r.bid] ~= nil
                r.star.Text = fav and "★" or "☆"
                r.star.TextColor3 = fav and C.STAR or C.TEXT_LO
                if onFav then onFav() end
            end)
        end
        return r
    end

    local function updateRow(r, di)
        local entry = data[di]
        if not entry then r.frame.Visible = false; r.bid = nil; return end
        local bid, bname = entry[1], entry[2]
        r.frame.Visible = true
        r.frame.Position = UDim2.new(0, 0, 0, (di - 1) * ROW_H)

        if bid == "##DIV##" then   -- fila divider (etiqueta de sección)
            r.isDiv = true; r.bid = nil; r.active = false
            r.frame.BackgroundTransparency = 1
            r.frame.Active = false
            r.st.Enabled = false; r.stAccent.Enabled = false
            r.thumb.Visible = false; r.name.Visible = false; r.sub.Visible = false
            r.star.Visible = false; r.act.Visible = false
            r.divLbl.Visible = true; r.divLbl.Text = string.upper(bname)
            return
        end

        r.isDiv = false
        r.frame.Active = true
        r.frame.BackgroundTransparency = 0.0
        r.st.Enabled = true
        r.divLbl.Visible = false
        r.thumb.Visible = true; r.name.Visible = true; r.sub.Visible = true
        r.star.Visible = showStar; r.act.Visible = true
        if r.bid ~= bid then
            r.bid = bid
            r.img.Image = thumbUrl(bid)
            r.name.Text = bname
            r.sub.Text = coverageText(bid)
        end
        local active = isActive and isActive(bid) or false
        r.active = active
        r.stAccent.Enabled = active
        r.frame.BackgroundColor3 = active and C.ROW_HOV or C.ROW
        if not showAct then         -- marcador de selección (mixer)
            r.act.Text = active and "✓" or ""
        end
        if showStar then
            local fav = favorites[bid] ~= nil
            r.star.Text = fav and "★" or "☆"
            r.star.TextColor3 = fav and C.STAR or C.TEXT_LO
        end
    end

    local function render()
        local top = sf.CanvasPosition.Y
        local start = math.max(1, math.floor(top / ROW_H))
        for i = 1, #pool do updateRow(pool[i], start + i - 1) end
    end

    local function setData(arr, resetScroll, emptyText)
        data = arr
        while #pool < POOL_N do pool[#pool + 1] = createRow() end
        sf.CanvasSize = UDim2.new(0, 0, 0, #data * ROW_H + 4)
        if resetScroll then sf.CanvasPosition = Vector2.new(0, 0) end
        emptyLbl.Visible = (#data == 0)
        if #data == 0 then emptyLbl.Text = emptyText or "Sin resultados" end
        render()
    end

    sf:GetPropertyChangedSignal("CanvasPosition"):Connect(render)
    return { frame = sf, setData = setData, render = render }
end

