local SLOT_H = 50
local DRAWER_MIN, DRAWER_MAX = 200, 340   -- alto TOTAL del acordeón (header + drawer)
local slotUI = {}
local expandedAtype = nil     -- ranura actualmente desplegada (solo una a la vez)

-- alto del acordeón según el espacio visible del scroller del Mix
local function drawerH()
    local vis = mixScroll.AbsoluteSize.Y
    if vis <= 0 then return DRAWER_MIN end
    return math.clamp(math.floor(vis * 0.82), DRAWER_MIN, DRAWER_MAX)
end

local function collapseSlot(atype)
    local s = slotUI[atype]
    if not s or not s.open then return end
    s.open = false
    s.arrow.Text = "↓"
    tween(s.drawer, DUR_MED, {Size = UDim2.new(1, 0, 0, 0)})
    tween(s.cont, DUR_MED, {Size = UDim2.new(1, -6, 0, SLOT_H)})
    tween(s.st, DUR_FAST, {Transparency = s.bid and 0.45 or 0.6})
    task.delay(DUR_MED, function() if not s.open then s.drawer.Visible = false end end)
    if expandedAtype == atype then expandedAtype = nil end
end

local function collapseAll()
    for _, at in ipairs(ANIM_TYPES) do collapseSlot(at) end
end

