    clr.AnchorPoint = Vector2.new(1, 0.5); clr.Position = UDim2.new(1, -10, 0.5, 0); clr.Size = UDim2.new(0, 28, 0, 28)
    clr.BackgroundColor3 = C.RED; clr.BackgroundTransparency = 0.75; clr.BorderSizePixel = 0
    clr.Text = "🗑️"; clr.TextColor3 = C.TEXT_HI; clr.FontFace = FONT_BOLD; clr.TextSize = 14; clr.AutoButtonColor = false
    clr.Visible = false
    corner(clr, 8)
    clr.MouseButton1Click:Connect(function() clearSlot(atype) end)
    addPress(clr)

    -- cajón desplegable (búsqueda + lista) — dentro del flujo, sin ventanas flotantes
    local drawer = Instance.new("Frame", cont)
    drawer.Position = UDim2.new(0, 0, 0, SLOT_H); drawer.Size = UDim2.new(1, 0, 0, 0)
    drawer.BackgroundTransparency = 1; drawer.ClipsDescendants = true; drawer.Visible = false

    local sBox = Instance.new("Frame", drawer)
    sBox.Position = UDim2.new(0, 10, 0, 6); sBox.Size = UDim2.new(1, -20, 0, 30)
    sBox.BackgroundColor3 = C.BG; sBox.BackgroundTransparency = 0.1; sBox.BorderSizePixel = 0
    corner(sBox, 9); local sStroke = glassStroke(sBox, 0.7, 1)
    local sBoxInput = Instance.new("TextBox", sBox)
    sBoxInput.BackgroundTransparency = 1; sBoxInput.Position = UDim2.new(0, 12, 0, 0); sBoxInput.Size = UDim2.new(1, -22, 1, 0)
    sBoxInput.FontFace = FONT; sBoxInput.PlaceholderText = "Buscar..."; sBoxInput.PlaceholderColor3 = C.TEXT_LO
    sBoxInput.Text = ""; sBoxInput.TextColor3 = C.TEXT_HI; sBoxInput.TextSize = 13; sBoxInput.TextXAlignment = Enum.TextXAlignment.Left
    sBoxInput.ClearTextOnFocus = false

    local listHolder = Instance.new("Frame", drawer)
    listHolder.Position = UDim2.new(0, 10, 0, 44); listHolder.Size = UDim2.new(1, -20, 1, -50)
    listHolder.BackgroundTransparency = 1

    local slotList = makeVirtualList(listHolder, 0,
        function(bid)
            assignSlot(atype, bid)     -- lógica MIX intacta
            collapseSlot(atype)
        end, nil,
        { showStar = false, showAct = false,
          isActive = function(bid) return mixSlots[atype] == bid end })

    slotUI[atype] = { cont = cont, hd = hd, ddTxt = ddTxt, arrow = ddArrow, clr = clr,
                      drawer = drawer, list = slotList, search = sBoxInput, st = st,
                      open = false, bid = "###" }

    -- búsqueda dentro del cajón (filtra su propia lista)
    local sToken = 0
    sBoxInput:GetPropertyChangedSignal("Text"):Connect(function()
        sToken = sToken + 1; local my = sToken
        task.delay(0.12, function()
            if my == sToken and slotUI[atype].open then
                slotList.setData(buildAnimsArray(sBoxInput.Text), true, "Sin resultados")
            end
        end)
    end)
    sStroke.Color = C.WHITE
    sBoxInput.Focused:Connect(function() sStroke.Color = C.ACCENT; sStroke.Transparency = 0.25 end)
    sBoxInput.FocusLost:Connect(function() sStroke.Color = C.WHITE; sStroke.Transparency = 0.7 end)

    local function openSlot()
        if expandedAtype and expandedAtype ~= atype then collapseSlot(expandedAtype) end
        local s = slotUI[atype]
        s.open = true; expandedAtype = atype
        s.arrow.Text = "↑"
        s.drawer.Visible = true
        s.search.Text = ""
        slotList.setData(buildAnimsArray(""), true, "Sin resultados")
        local h = drawerH()
        tween(s.drawer, DUR_MED, {Size = UDim2.new(1, 0, 0, h - SLOT_H)})
        tween(s.cont,   DUR_MED, {Size = UDim2.new(1, -6, 0, h)})
        tween(s.st, DUR_FAST, {Transparency = 0.3})
    end

    hd.MouseButton1Click:Connect(function()
        if slotUI[atype].open then collapseSlot(atype) else openSlot() end
    end)
    hd.MouseEnter:Connect(function() if not slotUI[atype].open then tween(cont, DUR_FAST, {BackgroundColor3 = C.ROW_HOV}) end end)
    hd.MouseLeave:Connect(function() if not slotUI[atype].open then tween(cont, DUR_FAST, {BackgroundColor3 = C.ROW}) end end)
end

