local function toast(msg, ok)
    local t = Instance.new("Frame", gui)
    t.Size = UDim2.new(0, 250, 0, 42); t.Position = UDim2.new(0.5, -125, 1, 30)
    t.BackgroundColor3 = C.SURFACE; t.BackgroundTransparency = 0.06; t.BorderSizePixel = 0; t.ZIndex = 80
    corner(t, 11); stroke(t, ok and C.ON or C.ACCENT, 1.2, 0.45)
    local bar = Instance.new("Frame", t); bar.Size = UDim2.new(0, 3, 1, -14); bar.Position = UDim2.new(0, 8, 0, 7)
    bar.BackgroundColor3 = ok and C.ON or C.ACCENT; bar.BorderSizePixel = 0; corner(bar, 2)
    local l = Instance.new("TextLabel", t)
    l.Size = UDim2.new(1, -28, 1, 0); l.Position = UDim2.new(0, 20, 0, 0); l.BackgroundTransparency = 1
    l.Text = msg; l.TextColor3 = C.TEXT_HI; l.FontFace = FONT_SEMI; l.TextSize = 13
    l.TextXAlignment = Enum.TextXAlignment.Left; l.TextTruncate = Enum.TextTruncate.AtEnd
    tween(t, DUR_MED, {Position = UDim2.new(0.5, -125, 1, -66)}, Enum.EasingStyle.Back)
    task.delay(2.2, function()
        if t and t.Parent then
            tween(t, DUR_MED, {Position = UDim2.new(0.5, -125, 1, 30), BackgroundTransparency = 1})
            task.delay(DUR_MED + 0.05, function() pcall(function() t:Destroy() end) end)
        end
    end)
end
