function refreshActiveCard()
    btnAuto.Text = "Auto: " .. (autoLoad and "ON" or "OFF")
    if activeMode == "full" and activeFull and DB[activeFull] then
        cardThumb.Visible = true; cardThumbImg.Image = thumbUrl(activeFull)
        cardName.Text = NAMES[activeFull] or ("Bundle " .. activeFull)
        cardSub.Text = (isApplied and "aplicado · " or "listo · ") .. coverageText(activeFull)
    elseif activeMode == "mix" and next(mixSlots) then
        cardThumb.Visible = false
        cardName.Text = "Mezcla personalizada"
        local names = {}
        for _, atype in ipairs(ANIM_TYPES) do if mixSlots[atype] then names[#names+1] = ANIM_SHORT[atype] end end
        cardSub.Text = (isApplied and "aplicado · mix · " or "listo · mix · ") .. table.concat(names, "·")
    else
        cardThumb.Visible = false
        cardName.Text = "Sin animación"
        cardSub.Text = "default · elige un pack abajo"
    end
    if currentTab == "anims" then animsList.render() end
end

function refreshAnims(resetScroll)
    animsList.setData(buildAnimsArray(search.Text), resetScroll, "Sin resultados")
end

function refreshFav()
    local arr = buildFavArray()
    local n = #arr
    favCount.Text = n .. (n == 1 and " favorita" or " favoritas")
    favList.setData(arr, false, "Sin favoritas aún — toca ☆ en un pack")
end

function refreshMix()
    for _, atype in ipairs(ANIM_TYPES) do
        local s = slotUI[atype]
        local bid = mixSlots[atype]
        if s.bid ~= bid then
            s.bid = bid
            if bid then
                s.ddTxt.Text = NAMES[bid] or ("Bundle " .. bid); s.ddTxt.TextColor3 = C.TEXT_HI
                s.st.Color = C.ACCENT; s.st.Transparency = s.open and 0.3 or 0.45
                s.clr.Visible = true
            else
                s.ddTxt.Text = "Vacío"; s.ddTxt.TextColor3 = C.TEXT_LO
                s.st.Color = C.WHITE; s.st.Transparency = s.open and 0.3 or 0.6
                s.clr.Visible = false
            end
        end
        if s.open then s.list.render() end   -- refresca el marcador de selección
    end
end

-- ========================================================================
-- ============================  ACCIONES  ===============================
-- ========================================================================
-- ★ los apply ahora corren en su propia tarea: el panel responde mientras se descarga,
--   y el guard evita que 3 clicks seguidos lancen 3 tandas de descargas encimadas.
local applyBusy = false

function applyFull(bid)          -- aplica pack completo. NO toca mixSlots.
    if applyBusy then toast("Espera, aún está cargando...", false) return end
    local first = not DB[bid] or not bundleCached(bid)
    if first then toast("⏳ Cargando " .. (NAMES[bid] or bid) .. "...", true) end
    applyBusy = true
    task.spawn(function()
        if not DB[bid] then                       -- ★ no está en cache → bajarlo del catálogo
            local got = fetchBundleLive(bid)
            if not got then
                applyBusy = false
                if alive() then toast("✗ No pude bajar ese pack (ID inválido o sin HTTP)", false) end
                return
            end
        end
        activeFull = bid
        activeMode = "full"
        projectFull(bid)
        pcall(applyFullMix)      -- motor intacto (lee currentMix)
        applyBusy = false
        if not alive() then return end
        saveConfig()
        if currentTab == "anims" then refreshAnims(false) elseif currentTab == "fav" then favList.render() end
        refreshActiveCard()
        toast("✓ " .. (NAMES[bid] or bid), true)
    end)
end

function applyMixPreset()        -- aplica el MIX (preset)
    if not next(mixSlots) then toast("El MIX está vacío", false) return end
    if applyBusy then toast("Espera, aún está cargando...", false) return end
    activeMode = "mix"
    activeFull = nil
    applyBusy = true
    task.spawn(function()
        projectMix()
        pcall(applyFullMix)
        applyBusy = false
        if not alive() then return end
        saveConfig()
        refreshActiveCard()
        if currentTab == "anims" then animsList.render() end
        toast("✓ Mix aplicado", true)
    end)
end

function assignSlot(atype, bid)  -- asigna un pack a una ranura del MIX (live)
    if applyBusy then toast("Espera, aún está cargando...", false) return end
    if not DB[bid] then          -- ★ no está en cache → bajarlo y reintentar
        toast("⏳ Bajando " .. (NAMES[bid] or bid) .. "...", true)
        task.spawn(function()
            local got = fetchBundleLive(bid)
            if not alive() then return end
            if got then assignSlot(atype, bid)
            else toast("✗ No pude bajar ese pack", false) end
        end)
        return
    end
    if not DB[bid][atype] then
        toast("Ese pack no tiene " .. ANIM_SHORT[atype], false) return
    end
    mixSlots[atype] = bid
    activeMode = "mix"
    activeFull = nil
    projectMix()
    refreshMix()                 -- feedback inmediato en la ranura
    applyBusy = true
    task.spawn(function()
        backupOriginals()
        local prep = nil
        local ok, res = pcall(prepareBundle, atype, bid)   -- descarga fuera del hilo de UI
        if ok then prep = res end
        if prep then
            commitPrepared(prep)                            -- swap instantáneo
            reloadAnimate()
            isApplied = true
        end
        applyBusy = false
        if not alive() then return end
        saveConfig()
        refreshMix()
        refreshActiveCard()
        toast("✓ " .. ANIM_SHORT[atype] .. " = " .. (NAMES[bid] or bid), true)
    end)
end

function clearSlot(atype)
    if not mixSlots[atype] then return end
    mixSlots[atype] = nil
    if activeMode == "mix" and isApplied then revertSlot(atype) end
    projectMix()
    saveConfig()
    refreshMix()
    refreshActiveCard()
    toast("Ranura " .. ANIM_SHORT[atype] .. " vaciada", true)
end

function doApplyActive()
    if activeMode == "mix" then applyMixPreset()
    elseif activeFull then applyFull(activeFull)
    else toast("Elige un pack primero", false) end
end

function reapplyCurrent()        -- reaplica el estado actual (respawn / auto-restore)
    if activeMode == "full" and activeFull and DB[activeFull] then
        projectFull(activeFull); applyFullMix()
    elseif activeMode == "mix" and next(mixSlots) then
        projectMix(); applyFullMix()
    end
end

