local grip = Instance.new("TextButton", main)
grip.AnchorPoint = Vector2.new(1, 1); grip.Position = UDim2.new(1, -3, 1, -3); grip.Size = UDim2.new(0, 18, 0, 18)
grip.BackgroundTransparency = 1; grip.Text = "◢"; grip.TextColor3 = C.TEXT_LO; grip.FontFace = FONT_BOLD
grip.TextSize = 13; grip.AutoButtonColor = false; grip.ZIndex = 40
do
    local resizing, rStart, rStartSize
    grip.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            resizing = true; rStart = input.Position; rStartSize = main.Size
            tween(grip, DUR_FAST, {TextColor3 = C.ACCENT})
        end
    end)
    UIS.InputChanged:Connect(function(input)
        if resizing and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
            local d = input.Position - rStart
            local w = math.clamp(rStartSize.X.Offset + d.X, MINW, MAXW)
            local h = math.clamp(rStartSize.Y.Offset + d.Y, MINH, MAXH)
            main.Size = UDim2.new(0, w, 0, h)
        end
    end)
    UIS.InputEnded:Connect(function(input)
        if resizing and (input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch) then
            resizing = false
            tween(grip, DUR_FAST, {TextColor3 = C.TEXT_LO})
        end
    end)
end
