local minimized = false
local savedH = DEF_H
local function playOpen()
    main.Visible = true; main.BackgroundTransparency = 1; mainScale.Scale = 0.94
    tween(main, DUR_SLOW, {BackgroundTransparency = 0.04})
    TweenService:Create(mainScale, TweenInfo.new(DUR_SLOW, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = 1}):Play()
end
local function playClose()
    tween(main, DUR_FAST, {BackgroundTransparency = 1})
    local tw = TweenService:Create(mainScale, TweenInfo.new(DUR_FAST, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {Scale = 0.94})
    tw:Play()
    tw.Completed:Connect(function() if not panelVisible then main.Visible = false end end)
end
closeBtn.MouseButton1Click:Connect(function() panelVisible = false; playClose() end)
minBtn.MouseButton1Click:Connect(function()
    minimized = not minimized
    if minimized then
        savedH = main.Size.Y.Offset
        content.Visible = false; tabStrip.Visible = false; grip.Visible = false
        tween(main, DUR_MED, {Size = UDim2.new(0, main.Size.X.Offset, 0, HEAD_H + 6)})
        minBtn.Text = "+"
    else
        content.Visible = true; tabStrip.Visible = true; grip.Visible = true
        tween(main, DUR_MED, {Size = UDim2.new(0, main.Size.X.Offset, 0, savedH)})
        minBtn.Text = "—"
    end
end)

