closeBtn.MouseLeave:Connect(function() tween(closeBtn, DUR_FAST, {BackgroundTransparency = 1, TextColor3 = C.TEXT_MID}) end)
minBtn.MouseEnter:Connect(function() tween(minBtn, DUR_FAST, {BackgroundTransparency = 0.82, TextColor3 = C.TEXT_HI}) end)
minBtn.MouseLeave:Connect(function() tween(minBtn, DUR_FAST, {BackgroundTransparency = 1, TextColor3 = C.TEXT_MID}) end)

UIS.InputBegan:Connect(function(input, gpe)
    if gpe then return end
    if input.KeyCode == TOGGLE_KEY and alive() then
        panelVisible = not panelVisible
        if panelVisible then playOpen() else playClose() end
    end
end)

-- ================= AUTO-RESTORE (debounce · una sola aplicación por respawn) =================
-- Antes: 2 rutas concurrentes (init + CharacterAdded) podían dispararse casi juntas
-- y reapplyCurrent corría 2 veces (o antes que Animate estuviera listo).
-- Ahora: un solo scheduler con token — si vuelve a llamarse, la anterior se anula.
local applyTok = 0
local function scheduleReapply(delay)
    if not (alive() and autoLoad and activeMode) then return end
    applyTok = applyTok + 1
    local my = applyTok
    task.delay(delay or 0.4, function()
        if my ~= applyTok then return end                        -- reemplazada por otra llamada
        if not (alive() and autoLoad and activeMode) then return end
        local char = LP.Character
        if not char then return end
        local animate = char:FindFirstChild("Animate")
        local hum     = char:FindFirstChildOfClass("Humanoid")
        if not (animate and hum and hum:FindFirstChildOfClass("Animator")) then
            scheduleReapply(0.35)                                 -- aún no listo · reintenta
            return
        end
        reapplyCurrent()
        refreshActiveCard()
    end)
end

-- Respawn
LP.CharacterAdded:Connect(function(char)
    if not (alive() and autoLoad and activeMode) then return end
    task.spawn(function()
        char:WaitForChild("Animate", 10)
        char:WaitForChild("Humanoid", 10)
        scheduleReapply(0.4)
    end)
end)

-- ================= INIT =================
refreshMix()
switchTab("anims")
panelVisible = true
playOpen()

-- auto-restore inicial (FULL o MIX) al ejecutar
task.spawn(function()
    if not (autoLoad and activeMode) then return end
    local char = LP.Character or LP.CharacterAdded:Wait()
    char:WaitForChild("Animate", 10)
    char:WaitForChild("Humanoid", 10)
    scheduleReapply(0.3)
end)

-- diagnóstico DB
do
    local dbCount = 0
    for _ in pairs(DB) do dbCount = dbCount + 1 end
    if dbCount == 0 then
        toast("No se leyó el cache (DB vacía)", false)
        warn("[NX Anims v2] No se pudo leer " .. CACHE_PATH)
    else
        warn("[NX Anims v2] Cargado: " .. dbCount .. " bundles · modo=" .. tostring(activeMode) .. " · autoLoad=" .. tostring(autoLoad))
    end
end
